import sys
sys.path.insert(0,'/workspace/build'); sys.path.insert(0,'/workspace/work')
import songdata as sd
names={}
for name in ['A1','A2','B1','B2','BRK','OUT']:
    mel=getattr(sd,name)
    print(f'=== {name} ===')
    for b,bar in enumerate(mel):
        pitches=[n for n,r in bar]
        rows=[r for n,r in bar]
        # intervals between successive notes
        def midi(s):
            step={'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
            i=2 if s[1]=='#' else 1
            return int(s[i:])*12+step[s[:i]]
        iv=[midi(pitches[i+1])-midi(pitches[i]) for i in range(len(pitches)-1)]
        print(f'  bar{b}: {" ".join(f"{p}@{r}" for p,r in bar)}')
        print(f'        intervals {iv}  range {min(map(midi,pitches))}-{max(map(midi,pitches))} rhythms {[rows[i+1]-rows[i] for i in range(len(rows)-1)]}')
EOF"}

