import sys
sys.path.insert(0,'/workspace/build'); sys.path.insert(0,'/workspace/work')
import songdata as sd
orig_put = sd.Pat.put
collisions=[]
def put(self, row, ch, note=0, inst=0, vol=None, fx=None, param=None):
    if (row,ch) in self.cells:
        collisions.append((row,ch,self.cells[(row,ch)],(note,inst,vol,fx,param)))
    return orig_put(self,row,ch,note,inst,vol,fx,param)
sd.Pat.put = put
pats,orders = sd.build()
for i,c in enumerate(collisions):
    print(i,'row',c[0],'ch',c[1],'old',c[2],'new',c[3])
EOF"}

